let fishes = [];
const NUM_FISH = 25;

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i = 0; i < NUM_FISH; i++) {
    fishes.push(new Fish(random(width), random(height), i));
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  background(12, 32, 58);

  let targetX = mouseX > 0 ? mouseX : width / 2;
  let targetY = mouseY > 0 ? mouseY : height / 2;
  let target = createVector(targetX, targetY);

  noStroke();
  fill(255, 230, 120, 40);
  circle(target.x, target.y, 30 + sin(frameCount * 0.1) * 6);
  fill(255, 240, 160, 180);
  circle(target.x, target.y, 8);

  for (let f of fishes) {
    f.update(target);
    f.display();
  }
}

function mousePressed() {
  let mouse = createVector(mouseX, mouseY);
  for (let f of fishes) {
    let d = dist(mouseX, mouseY, f.pos.x, f.pos.y);
    if (d < 150) {
      let scare = p5.Vector.sub(f.pos, mouse);
      scare.setMag(6);
      f.vel.add(scare);
    }
  }
}

class Fish {
  constructor(x, y, id) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(1, 3));
    this.acc = createVector(0, 0);
    this.maxSpeed = random(3, 5);
    this.maxForce = 0.15;
    this.size = random(14, 24);
    this.id = id;
    let colors = [
      color(255, 120, 50),
      color(255, 70, 110),
      color(40, 190, 230),
      color(255, 210, 60)
    ];
    this.col = colors[id % colors.length];
  }

  update(target) {
    let desired = p5.Vector.sub(target, this.pos);
    let d = desired.mag();
    let speed = this.maxSpeed;
    if (d < 100) {
      speed = map(d, 0, 100, 0.5, this.maxSpeed);
    }
    desired.setMag(speed);
    let steer = p5.Vector.sub(desired, this.vel);
    steer.limit(this.maxForce);
    this.acc.add(steer);

    for (let other of fishes) {
      if (other !== this) {
        let diff = p5.Vector.sub(this.pos, other.pos);
        let distVal = diff.mag();
        if (distVal > 0 && distVal < 30) {
          diff.normalize();
          diff.div(distVal);
          diff.mult(1.2);
          this.acc.add(diff);
        }
      }
    }

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  display() {
    let angle = this.vel.heading();
    push();
    translate(this.pos.x, this.pos.y);
    rotate(angle);

    let wiggle = sin(frameCount * 0.3 + this.id) * (this.size * 0.2);

    noStroke();
    fill(red(this.col), green(this.col), blue(this.col), 160);
    triangle(-this.size, 0, -this.size * 1.5, -this.size * 0.5 + wiggle, -this.size * 1.5, this.size * 0.5 + wiggle);

    fill(this.col);
    ellipse(0, 0, this.size * 1.8, this.size);

    fill(255);
    circle(this.size * 0.4, -this.size * 0.2, this.size * 0.3);
    fill(20);
    circle(this.size * 0.45, -this.size * 0.2, this.size * 0.15);

    pop();
  }
}

let fishes = [];
const NUM_FISH = 25;

function createFish(x, y, id) {
  let colors = [
    color(255, 120, 50),
    color(255, 70, 110),
    color(40, 190, 230),
    color(255, 210, 60)
  ];
  return {
    pos: createVector(x, y),
    vel: p5.Vector.random2D().mult(random(1, 3)),
    acc: createVector(0, 0),
    maxSpeed: random(3, 5),
    maxForce: 0.15,
    size: random(14, 24),
    id: id,
    col: colors[id % colors.length]
  };
}

function updateFish(f, target) {
  let desired = p5.Vector.sub(target, f.pos);
  let d = desired.mag();
  let speed = f.maxSpeed;
  if (d < 100) {
    speed = map(d, 0, 100, 0.5, f.maxSpeed);
  }
  desired.setMag(speed);
  let steer = p5.Vector.sub(desired, f.vel);
  steer.limit(f.maxForce);
  f.acc.add(steer);

  for (let other of fishes) {
    if (other !== f) {
      let diff = p5.Vector.sub(f.pos, other.pos);
      let distVal = diff.mag();
      if (distVal > 0 && distVal < 30) {
        diff.normalize();
        diff.div(distVal);
        diff.mult(1.2);
        f.acc.add(diff);
      }
    }
  }

  f.vel.add(f.acc);
  f.vel.limit(f.maxSpeed);
  f.pos.add(f.vel);
  f.acc.mult(0);
}

function displayFish(f) {
  let angle = f.vel.heading();
  push();
  translate(f.pos.x, f.pos.y);
  rotate(angle);

  let wiggle = sin(frameCount * 0.3 + f.id) * (f.size * 0.2);

  noStroke();
  fill(red(f.col), green(f.col), blue(f.col), 160);
  triangle(-f.size, 0, -f.size * 1.5, -f.size * 0.5 + wiggle, -f.size * 1.5, f.size * 0.5 + wiggle);

  fill(f.col);
  ellipse(0, 0, f.size * 1.8, f.size);

  fill(255);
  circle(f.size * 0.4, -f.size * 0.2, f.size * 0.3);
  fill(20);
  circle(f.size * 0.45, -f.size * 0.2, f.size * 0.15);

  pop();
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i = 0; i < NUM_FISH; i++) {
    fishes.push(createFish(random(width), random(height), i));
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  background(12, 32, 58);

  let targetX = mouseX > 0 ? mouseX : width / 2;
  let targetY = mouseY > 0 ? mouseY : height / 2;
  let target = createVector(targetX, targetY);

  noStroke();
  fill(255, 230, 120, 40);
  circle(target.x, target.y, 30 + sin(frameCount * 0.1) * 6);
  fill(255, 240, 160, 180);
  circle(target.x, target.y, 8);

  for (let f of fishes) {
    updateFish(f, target);
    displayFish(f);
  }
}

function mousePressed() {
  let mouse = createVector(mouseX, mouseY);
  for (let f of fishes) {
    let d = dist(mouseX, mouseY, f.pos.x, f.pos.y);
    if (d < 150) {
      let scare = p5.Vector.sub(f.pos, mouse);
      scare.setMag(6);
      f.vel.add(scare);
    }
  }
}
